package org.xar.ck3.control.wave2.military.combatwire.phaseevent;

import static org.xar.ck3.control.wave2.military.combatwire.phaseevent.PhaseJson.*;
import static org.xar.ck3.control.wave2.military.combatwire.phaseevent.PhaseConstants.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;

/** Strict AST interpretation. Every arithmetic result is checked after an exact-width-independent intermediate. */
final class PhaseAst {
    private PhaseAst() { }
    static int auditValue(JsonNode raw,Set<String> dependencies){ObjectNode n=object(raw,"value node");String op=text(n.get("op"),"op");int count=1;require(strings(VALUE_OPS,"value ops").contains(op),"unsupported value op "+op);
        switch(op){
        case "const_bool" -> {keys(n,"op value",op);bool(n.get("value"),op);}
        case "const_fixed" -> {keys(n,"op raw scale",op);signed(n.get("raw"),op);require(signed(n.get("scale"),op)==100000,"scale drifted");}
        case "state_ref" -> {keys(n,"op path value_type",op);require(dependencies.contains(text(n.get("path"),op)),"undeclared ref");require(Set.of("bool","fixed_q100000").contains(text(n.get("value_type"),op)),"unknown ref type");}
        case "all","any" -> {keys(n,"op args",op);ArrayNode args=array(n.get("args"),op);require(!args.isEmpty(),"empty logical args");for(JsonNode child:args)count+=auditValue(child,dependencies);}
        case "not" -> {keys(n,"op arg",op);count+=auditValue(n.get("arg"),dependencies);}
        case "compare" -> {keys(n,"op operator left right",op);require(Set.of("==","<","<=",">",">=").contains(text(n.get("operator"),op)),"unknown comparison");count+=auditValue(n.get("left"),dependencies)+auditValue(n.get("right"),dependencies);}
        case "subtract","multiply","divide" -> {keys(n,op.equals("subtract")?"op left right":"op left right rounding",op);if(!op.equals("subtract"))require(text(n.get("rounding"),op).equals("truncate_toward_zero"),"rounding drifted");count+=auditValue(n.get("left"),dependencies)+auditValue(n.get("right"),dependencies);}
        case "floor","ceiling" -> {keys(n,"op value limit",op);count+=auditValue(n.get("value"),dependencies)+auditValue(n.get("limit"),dependencies);}
        case "modifier_sequence" -> {keys(n,"op initial rounding modifiers final_weight_conversion",op);require(text(n.get("rounding"),op).equals("q100000_truncate_toward_zero_after_each_operation"),"modifier rounding drifted");require(text(n.get("final_weight_conversion"),op).equals("signed_q100000_divide_100000_truncate_toward_zero"),"weight conversion drifted");count+=auditValue(n.get("initial"),dependencies);for(JsonNode child:array(n.get("modifiers"),op))count+=auditValue(child,dependencies);}
        case "modifier" -> {keys(n,"op mode value condition",op);require(Set.of("add","factor").contains(text(n.get("mode"),op)),"modifier mode drifted");count+=auditValue(n.get("value"),dependencies)+auditValue(n.get("condition"),dependencies);}
        default -> throw new IllegalArgumentException("unsupported value op "+op);
        }return count;}
    static int auditEffect(JsonNode raw,Set<String> dependencies,Set<String> direct){ObjectNode n=object(raw,"effect node");String op=text(n.get("op"),"effect op");int count=1;
        switch(op){
        case "sequence" -> {keys(n,n.has("dependencies")?"op steps dependencies":"op steps",op);if(n.has("dependencies"))require(dependencies.containsAll(strings(n.get("dependencies"),op)),"unknown sequence dependency");ArrayNode steps=array(n.get("steps"),op);require(!steps.isEmpty(),"empty sequence");for(JsonNode child:steps)count+=auditEffect(child,dependencies,direct);}
        case "if" -> {keys(n,"op condition then else",op);count+=auditValue(n.get("condition"),dependencies)+auditEffect(n.get("then"),dependencies,direct)+auditEffect(n.get("else"),dependencies,direct);}
        case "select_side_knight" -> {keys(n,"op side filter weight order_policy on_selected",op);require(text(n.get("side"),op).equals("enemy")&&text(n.get("order_policy"),op).equals(MANIFEST_ORDER),"selection policy drifted");count+=auditValue(n.get("filter"),dependencies)+auditValue(n.get("weight"),dependencies)+auditEffect(n.get("on_selected"),dependencies,direct);}
        case "random_list" -> {keys(n,"op order_policy branches",op);require(text(n.get("order_policy"),op).equals("source_order"),"branch order drifted");ArrayNode branches=array(n.get("branches"),op);require(!branches.isEmpty(),"empty random list");for(JsonNode branch:branches)count+=auditEffect(branch,dependencies,direct);}
        case "random_branch" -> {keys(n,"op key base_weight validity weight effect",op);text(n.get("key"),op);count+=auditValue(n.get("base_weight"),dependencies)+auditValue(n.get("validity"),dependencies)+auditValue(n.get("weight"),dependencies)+auditEffect(n.get("effect"),dependencies,direct);}
        case "call_transition" -> {keys(n,"op key args dependencies",op);String key=text(n.get("key"),op);require(strings(DIRECT,"direct").contains(key),"unsupported direct transition "+key);require(dependencies.containsAll(strings(n.get("dependencies"),op)),"unknown transition dependency");transitionArgs(key,object(n.get("args"),"args"));direct.add(key);}
        default -> throw new IllegalArgumentException("unsupported effect op "+op);
        }return count;}
    private static void sameArgs(ObjectNode actual,String expected){require(actual.equals(parse(expected)),"transition args drifted");}
    private static void transitionArgs(String key,ObjectNode args){switch(key){
        case "no_op" -> require(args.isEmpty()||args.equals(parse("{\"empty_effect_maps_to_null_event\":true}")),"unknown no-op");
        case "increase_wound_or_die" -> sameArgs(args,"{\"target\":\"root\",\"reason\":\"fight\"}");
        case "maim_random" -> {keys(args,"target source_order_weights scale branches",key);require(text(args.get("target"),key).equals("root")&&signed(args.get("scale"),key)==100000&&args.get("source_order_weights").equals(parse("[400000,200000,400000,400000]"))&&args.get("branches").equals(MAIM),"maim signature drifted");}
        case "kill_character" -> {keys(args,"target reason killer",key);String target=text(args.get("target"),key),reason=text(args.get("reason"),key),killer=text(args.get("killer"),key);require((target.equals("root")&&reason.equals("death_battle")&&Set.of("selected_enemy_knight_or_null","selected_enemy_knight_if_both_alive_else_null").contains(killer))||(target.equals("selected_enemy_knight")&&reason.equals("death_head_ripped_off")&&killer.equals("root")),"kill signature drifted");}
        case "knight_increase_prowess_chance" -> {keys(args,"target",key);target(args.get("target"));}
        case "berserker_kill_random_reason" -> sameArgs(args,"{\"target\":\"selected_enemy_knight\",\"source_order_base_weights_raw\":[1000000,1000000,1000000,1000000,1000000,1000000,100000,1000000,1000000],\"fear_branch\":{\"invalid_if_brave\":true,\"add_raw_if_craven\":9900000,\"scale\":100000}}");
        case "shieldmaiden_kill_random_reason" -> sameArgs(args,"{\"target\":\"selected_enemy_knight\",\"source_order_weights_raw\":[1000000,1000000,1000000,1000000,1000000],\"scale\":100000}");
        case "add_trait" -> {keys(args,"target trait",key);require(text(args.get("target"),key).equals("root")&&Set.of("berserker","incapable").contains(text(args.get("trait"),key)),"trait signature drifted");}
        case "require_character_stat_recompute","require_participant_detach_recompute" -> {keys(args,"target timing",key);target(args.get("target"));require(text(args.get("timing"),key).equals("same_day_unverified"),"recompute timing drifted");}
        case "set_variable" -> {if(args.equals(parse("{\"target\":\"root.liege\",\"name\":\"accolade_progress\",\"value_raw\":0,\"scale\":100000}")))break;keys(args,"target name value",key);String name=text(args.get("name"),key);boolean found=false;for(JsonNode a:ACCOLADES)found|=name.equals(a.textValue()+"_attribute_unlock");require(text(args.get("target"),key).equals("root")&&bool(args.get("value"),key)&&found,"variable signature drifted");}
        case "observational_only" -> {keys(args,"effects",key);Set<String> effects=strings(args.get("effects"),key);require(!effects.isEmpty()&&strings(FEEDBACK,"feedback").containsAll(effects),"unsupported observation");}
        default -> throw new IllegalArgumentException("unknown transition "+key);
        }}
    private static void target(JsonNode target){require(Set.of("root","selected_enemy_knight").contains(text(target,"target")),"unsupported target");}
    static JsonNode value(JsonNode n,PhaseTrialState s,ObjectNode candidate){String op=text(n.get("op"),"value op");switch(op){
        case "const_bool":bool(n.get("value"),op);return n.get("value");
        case "const_fixed":require(signed(n.get("scale"),op)==100000,"scale drifted");signed(n.get("raw"),op);return n.get("raw");
        case "state_ref":{String path=text(n.get("path"),op),type=text(n.get("value_type"),op);JsonNode v=s.resolve(path,candidate);if(type.equals("bool"))bool(v,path);else if(type.equals("fixed_q100000"))signed(v,path);else throw new IllegalArgumentException("unsupported ref type");return v;}
        case "all":for(JsonNode child:array(n.get("args"),op))if(!booleanValue(child,s,candidate))return J.booleanNode(false);return J.booleanNode(true);
        case "any":for(JsonNode child:array(n.get("args"),op))if(booleanValue(child,s,candidate))return J.booleanNode(true);return J.booleanNode(false);
        case "not":return J.booleanNode(!booleanValue(n.get("arg"),s,candidate));
        case "compare":{JsonNode a=value(n.get("left"),s,candidate),b=value(n.get("right"),s,candidate);require(a.isBoolean()==b.isBoolean(),"unlike comparison types");String operator=text(n.get("operator"),op);if(operator.equals("=="))return J.booleanNode(a.isIntegralNumber()&&b.isIntegralNumber()?a.bigIntegerValue().equals(b.bigIntegerValue()):a.equals(b));require(!a.isBoolean(),"cannot order bool");int c=Long.compare(signed(a,op),signed(b,op));return J.booleanNode(switch(operator){case "<"->c<0;case "<="->c<=0;case ">"->c>0;case ">="->c>=0;default->throw new IllegalArgumentException("unsupported comparator");});}
        case "subtract","multiply","divide":{long a=fixed(n.get("left"),s,candidate),b=fixed(n.get("right"),s,candidate);return J.numberNode(switch(op){case "subtract"->subtract(a,b);case "multiply"->multiply(a,b);default->divide(a,b);});}
        case "floor","ceiling":{long a=fixed(n.get("value"),s,candidate),b=fixed(n.get("limit"),s,candidate);return J.numberNode(op.equals("floor")?Math.max(a,b):Math.min(a,b));}
        case "modifier_sequence":{long result=fixed(n.get("initial"),s,candidate);for(JsonNode m:array(n.get("modifiers"),op)){require(text(m.get("op"),op).equals("modifier"),"expected modifier");if(!booleanValue(m.get("condition"),s,candidate))continue;long v=fixed(m.get("value"),s,candidate);result=switch(text(m.get("mode"),op)){case "add"->add(result,v);case "factor"->multiply(result,v);default->throw new IllegalArgumentException("unknown modifier mode");};}return J.numberNode(result);}
        default:throw new IllegalArgumentException("unsupported value op "+op);
        }}
    static boolean booleanValue(JsonNode node,PhaseTrialState state,ObjectNode candidate){return bool(value(node,state,candidate),"boolean AST result");}
    static long fixed(JsonNode node,PhaseTrialState state,ObjectNode candidate){return signed(value(node,state,candidate),"fixed AST result");}
    static ObjectNode evaluateRow(StockPhaseManifest.Row row,PhaseTrialState state){boolean trigger=booleanValue(row.validity,state,null),role=state.roles.contains(row.type);long chance=fixed(row.chance,state,null),weight=chance/100000;ObjectNode out=obj().put("global_load_index",row.index).put("type_load_index",row.typeIndex).put("key",row.key).put("type",row.type).put("role_applicable",role).put("trigger_expression_value",trigger).put("trigger_valid",role&&trigger).put("chance_raw",chance).put("scale",100000).put("int_weight",weight).put("selectable_int_weight",role&&trigger?weight:0);out.set("effect_preflight",preflight(row.effect,state,row.key+".effect_ast"));return out;}
    record Materialized(List<ObjectNode> candidates,List<Long> weights,ObjectNode trace) { }
    static Materialized materialize(JsonNode node,PhaseTrialState state){List<ObjectNode> candidates=new ArrayList<>(state.candidates);ArrayNode source=arr(),evaluations=arr(),log=arr();candidates.forEach(c->source.add(c.get("character_id").deepCopy()));int index=0;while(index<candidates.size()){ObjectNode c=candidates.get(index);long id=positive(c.get("character_id"),"candidate id");log.add("shared:"+id);log.add("source:"+id);boolean valid=booleanValue(node.get("filter"),state,c);ObjectNode e=obj().put("index",index).put("character_id",id).put("shared_predicate",true).put("source_predicate",valid);if(valid){e.put("action","keep_advance");index++;}else{e.put("action","tail_swap_remove_recheck_same_index");if(index==candidates.size()-1)e.putNull("replacement_character_id");else e.set("replacement_character_id",candidates.get(candidates.size()-1).get("character_id").deepCopy());candidates.set(index,candidates.get(candidates.size()-1));candidates.remove(candidates.size()-1);}evaluations.add(e);}
        List<Long> weights=new ArrayList<>();ArrayNode ids=arr(),raw=arr(),ints=arr();for(ObjectNode c:candidates){long weight=fixed(node.get("weight"),state,c);weights.add(weight);ids.add(c.get("character_id").deepCopy());raw.add(weight);ints.add(PhaseDrawTape.nativeWeight(weight));}ObjectNode trace=obj();trace.set("source_character_ids_observed_v3",source);trace.put("candidate_source_proof_policy",PROOF_POLICY).set("candidate_source_sequence_sha256",state.proof.get("sequence_sha256").deepCopy());trace.put("source_vector_equivalence_ready",true).put("predicate_receiver_order","shared_then_source_empty_is_true").put("shared_predicate_projection","empty_true").put("source_predicate_projection","normalized_combined_filter_ast");trace.set("predicate_log",log);trace.set("limit_evaluations",evaluations);trace.set("post_compaction_character_ids",ids);trace.set("weights_raw_compacted_order",raw);trace.set("weights_int32_compacted_order",ints);return new Materialized(List.copyOf(candidates),List.copyOf(weights),trace);}
    static ObjectNode preflight(JsonNode node,PhaseTrialState s,String name){String op=text(node.get("op"),name);ObjectNode out=obj().put("op",op);switch(op){
        case "call_transition" -> out.set("key",node.get("key").deepCopy());
        case "sequence" -> {ArrayNode steps=out.putArray("steps");int i=0;for(JsonNode child:array(node.get("steps"),name))steps.add(preflight(child,s,name+".steps["+(i++)+"]"));}
        case "if" -> {boolean c=booleanValue(node.get("condition"),s,null);String branch=c?"then":"else";out.put("condition",c).put("selected_branch",branch);out.set("branch",preflight(node.get(branch),s,name+"."+branch));}
        case "select_side_knight" -> {Materialized m=materialize(node,s);ArrayNode rows=arr();for(int i=0;i<m.candidates.size();i++){ObjectNode c=m.candidates.get(i);Long previous=s.selected;s.selected=positive(c.get("character_id"),"candidate id");ObjectNode selected;try{selected=preflight(node.get("on_selected"),s,name+".on_selected");}finally{s.selected=previous;}ObjectNode row=obj();row.set("character_id",c.get("character_id").deepCopy());row.put("weight_raw",m.weights.get(i)).put("weight_int32",PhaseDrawTape.nativeWeight(m.weights.get(i)));row.set("on_selected",selected);rows.add(row);}out.put("side","enemy").put("order_policy",NATIVE_ORDER).put("algorithm_ready",true).put("materialization_input_ready",true).put("materialization_and_order_ready",true);out.set("materialization",m.trace);out.set("post_compaction_candidates",rows);}
        case "random_list" -> {out.put("order","source_order");ArrayNode branches=out.putArray("branches");for(JsonNode b:array(node.get("branches"),name)){boolean valid=booleanValue(b.get("validity"),s,null);long base=fixed(b.get("base_weight"),s,null),factor=fixed(b.get("weight"),s,null);ObjectNode row=obj();row.set("key",b.get("key").deepCopy());row.put("valid",valid).put("weight_raw",valid?multiply(base,factor):0);branches.add(row);}}
        default -> throw new IllegalArgumentException("unsupported effect preflight "+op);
        }return out.put("covered",true);}
    static void execute(JsonNode node,PhaseTrialState s,PhaseDrawTape tape,String name){String op=text(node.get("op"),name);switch(op){
        case "call_transition" -> PhaseTransitions.execute(text(node.get("key"),name),object(node.get("args"),name),s,tape);
        case "sequence" -> {int i=0;for(JsonNode child:array(node.get("steps"),name))execute(child,s,tape,name+".steps["+(i++)+"]");}
        case "if" -> {String branch=booleanValue(node.get("condition"),s,null)?"then":"else";execute(node.get(branch),s,tape,name+"."+branch);}
        case "select_side_knight" -> {Materialized m=materialize(node,s);int index=tape.takeNative(name+":enemy_knight",m.weights);ObjectNode log=obj().put("transition","select_side_knight").put("order_policy",NATIVE_ORDER);log.set("materialization",m.trace);ArrayNode ids=log.putArray("eligible_character_ids_compacted_order"),raw=log.putArray("weights_raw_compacted_order"),ints=log.putArray("weights_int32_compacted_order");if(index<0){log.putNull("selected_character_id");s.log.add(log);return;}s.selected=positive(m.candidates.get(index).get("character_id"),"selected");log.put("selected_character_id",s.selected);for(int i=0;i<m.candidates.size();i++){ids.add(m.candidates.get(i).get("character_id").deepCopy());raw.add(m.weights.get(i));ints.add(PhaseDrawTape.nativeWeight(m.weights.get(i)));}s.log.add(log);execute(node.get("on_selected"),s,tape,name+".on_selected");}
        case "random_list" -> {ArrayNode branches=array(node.get("branches"),name);List<Long> weights=new ArrayList<>();for(JsonNode b:branches)weights.add(booleanValue(b.get("validity"),s,null)?multiply(fixed(b.get("base_weight"),s,null),fixed(b.get("weight"),s,null)):0L);int index=tape.take(name+":random_list",weights);ObjectNode log=obj().put("transition","random_list");if(index<0)log.putNull("selected_branch");else log.set("selected_branch",branches.get(index).get("key").deepCopy());log.set("weights_source_order",tape.weights(weights));s.log.add(log);if(index>=0)execute(branches.get(index).get("effect"),s,tape,name+".branches["+index+"].effect");}
        default -> throw new IllegalArgumentException("unsupported effect op "+op);
        }}
}
